<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch,computed} from 'vue'
import {api,protectedObjectUrl,streamAgent} from './api'
import QuizAttemptPanel from './QuizAttemptPanel.vue'
import {renderMarkdown} from './htmlArtifacts'
import './forum.css'
import ExamWorkspace from './ExamWorkspace.vue'
import QuestionContent from './QuestionContent.vue'
type Point={id:number;name:string}
type Q={id:number;kind:string;body:string;options:string[];answer?:{values:string[]};explanation?:string;score:string|null;group?:{id:number;title:string;material:string;revision:number};source_id?:number;source_units?:number[];points:Point[];revision:number;active?:boolean}
type Quiz={id:number;title:string;status:string;opens_at:string;closes_at:string;answers_at:string;time_limit_minutes:number;max_attempts:number;grades_published:boolean;revision:number;rules?:{kind:string;count:number;point_id?:number}[]}
type Attempt={id:number;student_id:number;student_name?:string;quiz_id:number;number:number;status:string;paper:Q[];answers:Record<string,any>;answer_revision:number;saved_at:string|null;deadline:string;server_now:string;grading_status:string;scores?:Record<string,string|null>;feedback?:Record<string,string>;grade_revision?:number;total?:string|null;submission_basis:string;grade_history?:any[]}
const props=defineProps<{courseId:number;isTeacher:boolean;initialView?:'exams'|'bank';initialAttemptId?:number;ownerId?:number}>()
const emit=defineEmits<{focusChange:[focused:boolean];attemptChange:[id:number|undefined]}>()
const base=`courses/${props.courseId}/`
const kinds:Record<string,string>={single:'单选',multiple:'多选',boolean:'判断',blank:'填空',short:'简答'}
const quizzes=ref<Quiz[]>([]),questions=ref<Q[]>([]),points=ref<Point[]>([]),quiz=ref<Quiz|null>(null),attempts=ref<Attempt[]>([]),attempt=ref<Attempt|null>(null)
const gradingBase=ref('')
const aiBusy=ref(false),aiStatus=ref(''),aiElapsed=ref(0),aiItems=ref<{question_id:number;score:string|null;feedback:string;needs_reference:boolean}[]>([]),aiReady=ref(false)
let aiStarted=0
const busy=ref(false),loading=ref(true),error=ref(''),notice=ref(''),bank=ref(props.initialView==='bank'),create=ref(false),questionNext=ref<number|null>(null),attemptNext=ref<number|null>(null)
const qid=ref<number|null>(null),qrev=ref(0),kind=ref('single'),body=ref(''),optionText=ref('选项 A\n选项 B'),answerText=ref(''),explanation=ref(''),score=ref('10'),pointIds=ref<number[]>([]),active=ref(true)
const quizTitle=ref(''),opens=ref(''),closes=ref(''),answersAt=ref(''),minutes=ref(30),maxAttempts=ref(1),counts=ref<Record<string,number>>({single:1,multiple:1,boolean:1,blank:1,short:1}),rulePoint=ref('')
const randomScores=ref<Record<string,string>>({single:'10',multiple:'10',boolean:'10',blank:'10',short:'10'})
const localAnswers=ref<Record<string,any>>({}),saveState=ref(''),dirty=ref(false),saving=ref(false),remaining=ref(0),grade=ref<Record<string,string>>({}),feedback=ref<Record<string,string>>({}),reason=ref(''),suggestions=ref<{id:number;status:string;body:string;model:string}[]>([]),stats=ref<any>(null)
type ImportPreview={filename:string;total:number;valid_count:number;can_import:boolean;errors:{row:number;message:string}[];questions:{row:number;kind:string;body:string;options:string[];answer:{values:string[]};score:string;points:string[]}[]}
const importFile=ref<File|null>(null),importPreview=ref<ImportPreview|null>(null),importKey=ref('')
const exams=ref(props.initialView==='exams'),examRef=ref<InstanceType<typeof ExamWorkspace>|null>(null),fixedIds=ref<number[]>([]),fixedScores=ref<Record<string,string>>({})
const groups=ref<{id:number;title:string;material:string;revision:number;active:boolean;question_ids:number[]}[]>([]),selectedGroup=ref<number|null>(null)
const groupId=ref<number|null>(null),groupTitle=ref(''),groupMaterial=ref(''),groupRevision=ref(0),groupActive=ref(true)
const assemblyQuestions=ref<Q[]>([])
const batchScore=ref('5')
const assemblyTotal=computed(()=>fixedIds.value.reduce((sum,id)=>sum+Math.round(Number(fixedScores.value[id]||0)*100),0)/100)
const missingReferences=computed(()=>assemblyQuestions.value.filter(q=>!q.answer?.values.length).length)
function applyBatchScore(){if(!/^\d+(\.\d{1,2})?$/.test(batchScore.value)||Number(batchScore.value)<=0||Number(batchScore.value)>99999.99){error.value='每题分值须为 0.01 至 99999.99，最多两位小数';return}fixedScores.value=Object.fromEntries(fixedIds.value.map(id=>[id,batchScore.value]));error.value='';notice.value='已统一设置分值，仍可逐题调整'}
const cart=ref<{key:string;title:string;ids:number[]}[]>([]),groupOrder=ref<number[]>([])
// Save only selection IDs and scheduling fields, never private question/answer text.
const draftKey=props.ownerId&&props.isTeacher?`campusclaw.assembly.${props.ownerId}.${props.courseId}`:null
const recoveredDraft=ref<any>(null)
const draftStorageError=ref('')
function persistAssembly(){if(!draftKey)return;try{if(!cart.value.length&&!fixedIds.value.length&&!quizTitle.value.trim()){sessionStorage.removeItem(draftKey);return}sessionStorage.setItem(draftKey,JSON.stringify({version:1,cart:cart.value.map(v=>({key:v.key,ids:v.ids})),fixedIds:fixedIds.value,fixedScores:fixedScores.value,title:quizTitle.value,opens:opens.value,closes:closes.value,answersAt:answersAt.value,minutes:minutes.value,maxAttempts:maxAttempts.value}));draftStorageError.value=''}catch{draftStorageError.value='浏览器暂时无法保存组卷草稿，请勿刷新页面'}}
function readAssembly(){if(!draftKey)return;try{const raw=sessionStorage.getItem(draftKey);if(!raw)return;const value=JSON.parse(raw);if(value.version!==1||!Array.isArray(value.cart)||!Array.isArray(value.fixedIds)||value.cart.length>200||value.fixedIds.length>200)throw new Error();const validIds=(ids:unknown):ids is number[]=>Array.isArray(ids)&&ids.length<=200&&ids.every(i=>Number.isSafeInteger(i)&&i>0);if(!validIds(value.fixedIds)||!value.cart.every((v:any)=>typeof v.key==='string'&&validIds(v.ids)))throw new Error();recoveredDraft.value=value}catch{draftStorageError.value='本地组卷草稿无法读取，可清除后重新选题'}}
async function restoreAssembly(){const d=recoveredDraft.value;if(!d)return;const ids=[...new Set<number>([...d.fixedIds,...d.cart.flatMap((v:any)=>v.ids)])];await run(async()=>{const rows=new Map<number,Q>();let page:number|null=1;while(page&&rows.size<ids.length){const result:{items:Q[];next_page:number|null}=await api(base+`questions/?page=${page}`);for(const q of result.items)if(ids.includes(q.id)&&q.active!==false)rows.set(q.id,q);page=result.next_page}const missing=ids.filter(id=>!rows.has(id));if(missing.length)throw new Error(`${missing.length} 道已选题目已停用或不可访问，请清除草稿后重新选题`);cart.value=d.cart.map((v:any)=>({key:v.key,ids:v.ids,title:v.key.startsWith('g')?groups.value.find(g=>'g'+g.id===v.key)?.title||'已保存题组':rows.get(v.ids[0])?.body.slice(0,40)||'已选题目'}));if(d.fixedIds.length){assemblyQuestions.value=d.fixedIds.map((id:number)=>rows.get(id)!);fixedIds.value=d.fixedIds;fixedScores.value=Object.fromEntries(d.fixedIds.map((id:number)=>[id,['string','number'].includes(typeof d.fixedScores?.[id])?String(d.fixedScores[id]):'']));exams.value=false;bank.value=false;create.value=true}for(const [target,key] of [[quizTitle,'title'],[opens,'opens'],[closes,'closes'],[answersAt,'answersAt']] as const)target.value=typeof d[key]==='string'?d[key].slice(0,200):'';minutes.value=Number.isInteger(d.minutes)&&d.minutes>=1&&d.minutes<=240?d.minutes:30;maxAttempts.value=Number.isInteger(d.maxAttempts)&&d.maxAttempts>=1&&d.maxAttempts<=10?d.maxAttempts:1;recoveredDraft.value=null;notice.value='已恢复选题与组卷设置；题目内容已从服务器重新核对'})}
function clearAssembly(){if(!confirm('清除本浏览器保存的选题及组卷草稿？不会删除题库或已有测验。'))return;recoveredDraft.value=null;cart.value=[];fixedIds.value=[];fixedScores.value={};create.value=false;quizTitle.value='';try{if(draftKey)sessionStorage.removeItem(draftKey);draftStorageError.value=''}catch{draftStorageError.value='浏览器无法清除本地草稿'}}
readAssembly()
watch([cart,fixedIds,fixedScores,quizTitle,opens,closes,answersAt,minutes,maxAttempts],()=>{if(!recoveredDraft.value)persistAssembly()},{deep:true})
function addCart(key:string,title:string,ids:number[]){if(cart.value.some(v=>v.key===key)){notice.value='这项已经在选题篮中';return}cart.value.push({key,title,ids});notice.value='已加入选题篮，可继续选题，再统一设置分值'}
function moveCart(index:number,delta:number){const target=index+delta;if(target<0||target>=cart.value.length)return;[cart.value[index],cart.value[target]]=[cart.value[target],cart.value[index]]}
function moveGroupQuestion(index:number,delta:number){const target=index+delta;if(target<0||target>=groupOrder.value.length)return;[groupOrder.value[index],groupOrder.value[target]]=[groupOrder.value[target],groupOrder.value[index]]}
async function assemble(ids:number[]){if(!canLeave())return;await run(async()=>{const selected=new Map(questions.value.filter(q=>ids.includes(q.id)).map(q=>[q.id,q]));let page:number|null=1;while(page&&selected.size<ids.length){const result:{items:Q[];next_page:number|null}=await api(base+`questions/?page=${page}`);for(const q of result.items)if(ids.includes(q.id))selected.set(q.id,q);page=result.next_page}if(selected.size!==ids.length)throw new Error('部分题目已不可访问，请重新选题');assemblyQuestions.value=ids.map(id=>selected.get(id)!);fixedIds.value=ids;fixedScores.value=Object.fromEntries(ids.map(id=>[id,'']));exams.value=false;bank.value=false;create.value=true;quiz.value=null;attempt.value=null})}
async function loadGroups(){const items:typeof groups.value=[];let page:number|null=1;while(page){const result: {items:typeof groups.value;next_page:number|null}=await api(base+`question-groups/?page=${page}`);items.push(...result.items);page=result.next_page}groups.value=items}
function editGroup(id?:number){const g=groups.value.find(g=>g.id===id);groupId.value=g?.id||null;groupTitle.value=g?.title||'';groupMaterial.value=g?.material||'';groupRevision.value=g?.revision||0;groupActive.value=g?.active!==false;groupOrder.value=[...(g?.question_ids||[])]}
async function saveGroup(){await run(async()=>{await api(groupId.value?`question-groups/${groupId.value}/`:base+'question-groups/',groupId.value?'PUT':'POST',{title:groupTitle.value,material:groupMaterial.value,active:groupActive.value,...(groupId.value?{question_ids:groupOrder.value}:{}),expected_revision:groupRevision.value});await loadGroups();await loadBank();editGroup();notice.value='题组已保存，已有答卷仍使用开考快照'})}
async function addPicture(event:Event,target:'body'|'explanation'|'group'){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await run(async()=>{const form=new FormData();form.append('file',file);const asset=await api<{marker:string}>(base+'question-assets/','POST',form);if(target==='body')body.value+='\n'+asset.marker;else if(target==='explanation')explanation.value+='\n'+asset.marker;else groupMaterial.value+='\n'+asset.marker})}
async function editById(id:number){await run(async()=>{let page:number|null=1;let found=false;while(page){const result:{items:Q[];next_page:number|null}=await api(base+`questions/?page=${page}`);const q=result.items.find(q=>q.id===id);if(q){edit(q);found=true;break}page=result.next_page}if(!found)throw new Error('题目不存在或无权编辑');exams.value=false;bank.value=true;await loadBank();await loadGroups()})}
let saveTimer:ReturnType<typeof setTimeout>|undefined,ticker:ReturnType<typeof setInterval>|undefined
let lastServerNow=0,lastMonotonic=0
async function run(action:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await action()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function list(){quizzes.value=await api<Quiz[]>(base+'quizzes/')}
const bankSearch=ref(''),bankKind=ref(''),bankPoint=ref(''),bankAnswer=ref(''),bankActive=ref('')
let bankGeneration=0
let appliedBankFilters={q:'',kind:'',point_id:'',answer_state:'',active:''}
function resetBankFilters(){bankSearch.value='';bankKind.value='';bankPoint.value='';bankAnswer.value='';bankActive.value='';void run(()=>loadBank())}
async function toggleQuestion(q:Q){if(!confirm(q.active===false?'恢复这道题供后续组卷使用？':'停用这道题？历史试卷与成绩保留，新组卷不再选用。'))return;await run(async()=>{await api(`questions/${q.id}/`,'PUT',{...q,point_ids:q.points.map(p=>p.id),active:q.active===false,expected_revision:q.revision});await loadBank();notice.value='题目状态已更新，历史答卷保留'})}
async function loadBank(page=1){const generation=++bankGeneration;const filters=page===1?{q:bankSearch.value,kind:bankKind.value,point_id:bankPoint.value,answer_state:bankAnswer.value,active:bankActive.value}:{...appliedBankFilters};const params=new URLSearchParams({page:String(page),...filters});const result=await api<{items:Q[];next_page:number|null}>(base+'questions/?'+params);if(generation!==bankGeneration)return;appliedBankFilters=filters;questions.value=page===1?result.items:[...questions.value,...result.items];questionNext.value=result.next_page}
async function select(q:Quiz){await run(async()=>{quiz.value=q;attempt.value=null;stats.value=null;bank.value=false;create.value=false;await loadAttempts()})}
async function loadAttempts(page=1){if(!quiz.value){attempts.value=[];attemptNext.value=null;return}const data=await api<{items:Attempt[];next_page:number|null}>(`quizzes/${quiz.value!.id}/attempts/?page=${page}`);attempts.value=page===1?data.items:[...attempts.value,...data.items];attemptNext.value=data.next_page}
function edit(q?:Q){qid.value=q?.id||null;qrev.value=q?.revision||0;kind.value=q?.kind||'single';body.value=q?.body||'';optionText.value=q?.options.join('\n')||'选项 A\n选项 B';answerText.value=q?.answer?.values.join('\n')||'';explanation.value=q?.explanation||'';score.value=q?.score||'10';pointIds.value=q?.points.map(p=>p.id)||[];active.value=q?.active!==false;selectedGroup.value=q?.group?.id||null}
async function saveQuestion(){await run(async()=>{await api(qid.value?`questions/${qid.value}/`:base+'questions/',qid.value?'PUT':'POST',{kind:kind.value,body:body.value,options:['single','multiple'].includes(kind.value)?optionText.value.split('\n').filter(x=>x.trim()):[],answer:{values:answerText.value.split('\n').filter(x=>x.trim())},explanation:explanation.value,group_id:selectedGroup.value,point_ids:pointIds.value,active:active.value,expected_revision:qrev.value});edit();await loadBank();notice.value='题目已保存，已开始的试卷保持原快照'})}
async function previewImport(file?:File){importFile.value=file||null;importPreview.value=null;importKey.value='';if(!file)return;await run(async()=>{const form=new FormData();form.append('file',file);importPreview.value=await api<ImportPreview>(base+'questions/import/preview/','POST',form);if(importPreview.value.can_import)importKey.value=crypto.randomUUID()})}
async function commitImport(){if(!importFile.value||!importPreview.value?.can_import||!importKey.value)return;await run(async()=>{const form=new FormData();form.append('file',importFile.value!);form.append('request_key',importKey.value);const result=await api<{imported_count:number;replayed:boolean}>(base+'questions/import/commit/','POST',form);notice.value=result.replayed?`已确认原导入结果：${result.imported_count} 道题，没有重复创建。`:`已导入 ${result.imported_count} 道题。`;importFile.value=null;importPreview.value=null;importKey.value='';const input=document.querySelector<HTMLInputElement>('#question-import-file');if(input)input.value='';await loadBank()})}
async function downloadQuestionTemplate(format:'xlsx'|'docx'){await run(async()=>{const objectUrl=await protectedObjectUrl(`/api/question-import-template/${format}/`);const link=document.createElement('a');link.href=objectUrl;link.download=`CampusClaw-question-bank-template.${format}`;link.click();setTimeout(()=>URL.revokeObjectURL(objectUrl),1000)})}
async function createQuiz(){
  await run(async()=>{
    const selection=fixedIds.value.length
      ? {question_ids:fixedIds.value,question_scores:fixedScores.value}
      : {rules:Object.keys(kinds).filter(kind=>counts.value[kind]>0).map(kind=>({
          kind,
          count:counts.value[kind],
          score:String(randomScores.value[kind]),
          ...(rulePoint.value?{point_id:Number(rulePoint.value)}:{})
        }))}
    await api(base+'quizzes/','POST',{
      title:quizTitle.value,
      opens_at:new Date(opens.value).toISOString(),
      closes_at:new Date(closes.value).toISOString(),
      answers_at:new Date(answersAt.value).toISOString(),
      time_limit_minutes:minutes.value,
      max_attempts:maxAttempts.value,
      ...selection
    })
    create.value=false;quizTitle.value='';cart.value=[];fixedIds.value=[];fixedScores.value={}
    await list()
    notice.value='测验草稿已创建，请核对后发布'
  })
}
async function action(value:string){await run(async()=>{quiz.value=await api<Quiz>(`quizzes/${quiz.value!.id}/publish/`,'POST',{action:value});await list();await loadAttempts()})}
function setAttempt(a:Attempt){attempt.value=a;localAnswers.value=JSON.parse(JSON.stringify(a.answers));dirty.value=false;saveState.value=a.saved_at?'已恢复服务器保存的答案':'尚未保存答案';lastServerNow=Date.parse(a.server_now);lastMonotonic=performance.now();remaining.value=Math.max(0,Math.ceil((Date.parse(a.deadline)-lastServerNow)/1000));grade.value=Object.fromEntries(a.paper.map(q=>[q.id,a.scores?.[q.id]??'']));feedback.value={...(a.feedback||{})};reason.value='';suggestions.value=[];aiItems.value=[];aiReady.value=false;aiStatus.value='';gradingBase.value=JSON.stringify({scores:grade.value,feedback:feedback.value})}
async function start(){await run(async()=>{const a=await api<Attempt>(`quizzes/${quiz.value!.id}/attempts/`,'POST',{});setAttempt(a)})}
let attemptLoadGeneration=0
async function openAttempt(id:number){const generation=++attemptLoadGeneration;await run(async()=>{const result=await api<Attempt>(`quiz-attempts/${id}/`);if(generation!==attemptLoadGeneration)return;quiz.value=quizzes.value.find(q=>q.id===result.quiz_id)??null;setAttempt(result);if(props.isTeacher){const rows=await api<typeof suggestions.value>(`quiz-attempts/${id}/suggestion/`);if(generation!==attemptLoadGeneration||attempt.value?.id!==id)return;suggestions.value=rows;loadSuggestion()}})}
function changed(){dirty.value=true;saveState.value='有未保存修改';if(saveTimer)clearTimeout(saveTimer);saveTimer=setTimeout(()=>void save(),800)}
async function save(){if(!attempt.value||props.isTeacher||!dirty.value||saving.value||attempt.value.status!=='in_progress')return;saving.value=true;const a=attempt.value;const answers=JSON.parse(JSON.stringify(localAnswers.value));saveState.value='正在保存…';try{const result=await api<{answer_revision:number;saved_at:string}>(`quiz-attempts/${a.id}/answers/`,'PUT',{answers,expected_revision:a.answer_revision,key:crypto.randomUUID()});if(attempt.value?.id!==a.id)return;a.answer_revision=result.answer_revision;a.saved_at=result.saved_at;dirty.value=JSON.stringify(localAnswers.value)!==JSON.stringify(answers);saveState.value=dirty.value?'有新的未保存修改':'已保存到服务器';if(dirty.value)saveTimer=setTimeout(()=>void save(),500)}catch(e){saveState.value='保存失败：'+(e instanceof Error?e.message:'请检查网络');error.value=saveState.value}finally{saving.value=false}}
async function submit(){await run(async()=>{await save();if(dirty.value)throw new Error('仍有未保存答案，请先核对保存状态；如已到期将使用服务器最后保存内容');setAttempt(await api<Attempt>(`quiz-attempts/${attempt.value!.id}/submit/`,'POST',{}));await loadAttempts();notice.value='已交卷，答案不可再修改'})}
async function refreshAttempt(){if(aiBusy.value)return;await run(async()=>{if(props.isTeacher&&gradingBase.value!==JSON.stringify({scores:grade.value,feedback:feedback.value})&&!confirm('刷新将丢弃未保存的评分草稿，继续？'))return;if(dirty.value&&!confirm('刷新会丢弃未保存的本地修改，继续？'))return;setAttempt(await api<Attempt>(`quiz-attempts/${attempt.value!.id}/`))})}
async function upload(q:Q,event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file||!attempt.value)return;await run(async()=>{const form=new FormData();form.append('file',file);const data=await api<{id:number}>(`quiz-attempts/${attempt.value!.id}/images/${q.id}/`,'POST',form);const answer=localAnswers.value[q.id]||{text:'',image_ids:[]};answer.image_ids=[...(answer.image_ids||[]),data.id];localAnswers.value[q.id]=answer;changed()})}
async function review(){await run(async()=>{setAttempt(await api<Attempt>(`quiz-attempts/${attempt.value!.id}/review/`,'POST',{scores:grade.value,feedback:feedback.value,reason:reason.value,expected_revision:attempt.value!.grade_revision}));await loadAttempts();notice.value='正式评分已保存，保留修订历史'})}
function loadSuggestion(){aiItems.value=[];aiReady.value=false;const latest=suggestions.value.find(s=>s.status==='awaiting_review');if(!latest)return;try{const data=JSON.parse(latest.body);if(data.answer_encoding_version===2&&data.grade_revision===attempt.value?.grade_revision){aiItems.value=data.items;aiReady.value=true;aiStatus.value='已恢复上次逐题评阅，可选择采纳'}}catch{/* Older prose remains available in history. */}}
async function suggest(){if(aiBusy.value||!attempt.value)return;const id=attempt.value.id;aiBusy.value=true;aiStarted=Date.now();aiElapsed.value=0;aiItems.value=[];aiReady.value=false;aiStatus.value='正在连接 AI 评阅…';error.value='';try{let completed=false;await streamAgent(`quiz-attempts/${id}/suggestion/`,{stream:true},{onEvent:(type,payload)=>{if(type==='status')aiStatus.value=payload.text;if(type==='item')aiItems.value.push(payload);if(type==='complete'){aiItems.value=payload.items;aiReady.value=true;completed=true;aiStatus.value='评阅完成，请逐题核对后采纳';}if(type==='error'){error.value=payload.error;aiStatus.value=payload.error;aiReady.value=false}}});if(!completed&&!error.value)throw new Error('评阅连接中断，请重试；正式成绩未改变');suggestions.value=await api(`quiz-attempts/${id}/suggestion/`)}catch(e){error.value=e instanceof Error?e.message:'评阅失败，请重试';aiStatus.value=error.value;aiReady.value=false}finally{aiBusy.value=false}}
function adoptSuggestion(id:number){if(!aiReady.value||aiBusy.value)return;const row=aiItems.value.find(r=>r.question_id===id);if(!row||row.score===null)return;grade.value[id]=row.score;feedback.value[id]=row.feedback;reason.value||='教师核对并采纳 AI 评阅建议';notice.value='已填入评分草稿，保存正式评分后才生效'}
function shortAnswer(q:Q){if(!localAnswers.value[q.id])localAnswers.value[q.id]={text:'',image_ids:[]};return localAnswers.value[q.id]}
function canLeave(){if(props.isTeacher&&attempt.value&&gradingBase.value!==JSON.stringify({scores:grade.value,feedback:feedback.value})&&!confirm('评分草稿尚未保存，确定离开？'))return false;if(aiBusy.value){notice.value='AI 正在评阅，请完成后再离开';return false;}if(exams.value&&examRef.value&&!examRef.value.canLeave())return false;return !dirty.value||confirm('仍有未保存答案，离开会丢失本地修改。继续？')}
async function leaveAttempt(){if(!canLeave())return;if(saveTimer)clearTimeout(saveTimer);attempt.value=null;dirty.value=false;await run(()=>loadAttempts())}
function answerLabel(q:Q,value:unknown){if(value==null)return '未作答';if(q.kind==='short')return (value as {text?:string}).text||'（无文本）';if(q.kind==='multiple')return (value as string[]).map(v=>q.options[Number(v)]).join('；')||'未作答';if(q.kind==='single')return q.options[Number(value)]||'未作答';if(q.kind==='boolean')return value==='true'?'正确':'错误';return String(value)}
defineExpose({canLeave})
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value||aiBusy.value||(props.isTeacher&&attempt.value&&gradingBase.value!==JSON.stringify({scores:grade.value,feedback:feedback.value}))){event.preventDefault();event.returnValue=''}}
onMounted(async()=>{await run(async()=>{await list();points.value=await api<Point[]>(base+'forum/points/');if(props.isTeacher){await loadBank();await loadGroups()}if(props.initialAttemptId)await openAttempt(props.initialAttemptId)});loading.value=false;window.addEventListener('beforeunload',beforeUnload);ticker=setInterval(()=>{if(aiBusy.value)aiElapsed.value=Math.floor((Date.now()-aiStarted)/1000);const a=attempt.value;if(!a||a.status!=='in_progress')return;remaining.value=Math.max(0,Math.ceil((Date.parse(a.deadline)-lastServerNow-(performance.now()-lastMonotonic))/1000));if(!props.isTeacher&&remaining.value===0&&!busy.value){void run(async()=>{setAttempt(await api<Attempt>(`quiz-attempts/${a.id}/submit/`,'POST',{}));notice.value='已到截止时间，按服务器最后成功保存的答案交卷'})}},1000)})
watch(()=>attempt.value?.id,()=>{emit('focusChange',!!attempt.value);emit('attemptChange',attempt.value?.id)})
watch(()=>props.initialAttemptId,id=>{if(id!==undefined&&id===attempt.value?.id)return;attemptLoadGeneration++;if(id===attempt.value?.id)return;if(id)void openAttempt(id);else{if(saveTimer)clearTimeout(saveTimer);attempt.value=null;dirty.value=false;void run(()=>loadAttempts())}})

onUnmounted(()=>{bankGeneration++;attemptLoadGeneration++;emit('focusChange',false);if(ticker)clearInterval(ticker);if(saveTimer)clearTimeout(saveTimer);window.removeEventListener('beforeunload',beforeUnload)})
</script>

<template>
<section class="quiz-workspace forum-workspace" aria-label="测验与题库"><div v-if="!attempt" class="section-head"><div><h2>{{exams?'试卷识别':bank?'我的题库':'测验'}}</h2><p>上传试卷整理入库，选题组卷，作答后自动判客观题、AI 辅助评阅主观题。</p></div><div v-if="isTeacher" class="forum-actions"><button class="secondary" @click="if(canLeave()){exams=!exams;bank=false;create=false;quiz=null;attempt=null}">试卷识别与整理</button><button class="secondary" @click="if(canLeave()){exams=false;bank=!bank;quiz=null;attempt=null;create=false}">管理题库</button><button class="primary" @click="if(canLeave()){exams=false;fixedIds=[];create=true;bank=false;quiz=null;attempt=null}">创建测验</button></div></div>
<p v-if="loading" role="status">正在加载…</p><p v-if="error&&!attempt" role="alert" class="error">{{error}}</p><p v-if="notice&&!attempt" role="status">{{notice}}</p>
<section v-if="isTeacher&&(recoveredDraft||draftStorageError)" class="forum-card" aria-label="恢复组卷草稿"><p role="status">{{draftStorageError||'此浏览器保存了一份选题 / 组卷草稿，可恢复继续编辑。'}}</p><button v-if="recoveredDraft" class="primary" :disabled="busy||loading" @click="restoreAssembly">恢复组卷草稿</button><button class="secondary" :disabled="busy" @click="clearAssembly">清除组卷草稿</button><p>仅当前浏览器标签页保存，退出登录会清除。私有题干与答案不会写入浏览器草稿。</p></section><ExamWorkspace v-if="exams&&isTeacher" ref="examRef" :course-id="courseId" @assemble="assemble" @changed="run(async()=>{await loadBank();await loadGroups()})" @edit-question="editById"/><template v-else-if="bank&&isTeacher"><section class="forum-card forum-form"><h3>选题篮</h3><p v-if="!cart.length">选择整组材料题或独立题，按所选顺序组合试卷。</p><div v-for="(entry,index) in cart" :key="entry.key" class="forum-actions"><span>{{index+1}}. {{entry.title}} · {{entry.ids.length}} 题</span><button class="secondary" :disabled="index===0" @click="moveCart(index,-1)">上移</button><button class="secondary" :disabled="index===cart.length-1" @click="moveCart(index,1)">下移</button><button class="secondary" @click="cart.splice(index,1)">移出</button></div><button class="primary" :disabled="!cart.length" @click="assemble(cart.flatMap(v=>v.ids))">用选题篮创建测验</button><h3>我的材料题组</h3><p>共享文章、条件和配图，组卷时整体选入。分值在组卷时设置。</p><div v-for="g in groups" :key="g.id" class="forum-actions"><strong>{{g.title}} · {{g.question_ids.length}} 小题 {{g.active?'':'已停用'}}</strong><button class="secondary" @click="editGroup(g.id)">编辑材料</button><button class="secondary" :disabled="!g.active||!g.question_ids.length" @click="addCart('g'+g.id,g.title,g.question_ids)">加入选题篮</button></div><div v-if="groupId"><h4>小题顺序</h4><div v-for="(id,index) in groupOrder" :key="id" class="forum-actions"><span>题 #{{id}}</span><button class="secondary" :disabled="index===0" @click="moveGroupQuestion(index,-1)">上移小题</button><button class="secondary" :disabled="index===groupOrder.length-1" @click="moveGroupQuestion(index,1)">下移小题</button></div></div><details :open="!!groupId" class="bank-editor"><summary>{{groupId?'编辑题组材料':'新建共享材料题组'}}</summary><label>题组标题<input v-model="groupTitle" maxlength="200"></label><label>共享材料<textarea v-model="groupMaterial" rows="6" maxlength="30000"></textarea></label><label>材料配图<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy" @change="addPicture($event,'group')"></label><QuestionContent :text="groupMaterial"/><label><input v-model="groupActive" type="checkbox">启用题组</label><div class="forum-actions"><button class="primary" :disabled="busy||!groupTitle.trim()" @click="saveGroup">保存题组</button><button class="secondary" @click="editGroup()">新建题组</button></div></details></section><details class="forum-card question-import"><summary>使用 Excel / Word 模板批量导入</summary><div class="section-head"><div><h3>批量导入题目</h3><p>XLSX 单工作表或 DOCX 单表格 · 每批最多 200 题、5 MiB</p></div><div class="forum-actions"><button type="button" class="secondary" :disabled="busy" @click="downloadQuestionTemplate('xlsx')">下载 Excel 模板</button><button type="button" class="secondary" :disabled="busy" @click="downloadQuestionTemplate('docx')">下载 Word 模板</button></div></div><p>按模板逐列填写。选项、答案和知识点均每行一个；选择题答案可填 A/B/C，判断填正确/错误。知识点须与本课程已启用名称完全一致。旧版 .xls/.doc 请先另存为 .xlsx/.docx。</p><label for="question-import-file">选择题库文件</label><input id="question-import-file" type="file" accept=".xlsx,.docx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.openxmlformats-officedocument.wordprocessingml.document" :disabled="busy" @change="previewImport(($event.target as HTMLInputElement).files?.[0])"><p v-if="importPreview" role="status">{{importPreview.filename}} · {{importPreview.valid_count}} / {{importPreview.total}} 行通过</p><ul v-if="importPreview?.errors.length" class="import-errors"><li v-for="(item,index) in importPreview.errors" :key="index">第 {{item.row}} 行：{{item.message}}</li></ul><article v-for="item in importPreview?.questions" :key="item.row" class="import-preview-row"><strong>第 {{item.row}} 行 · {{kinds[item.kind]}} · {{item.score}} 分</strong><div class="markdown-body" v-html="renderMarkdown(item.body)"></div><p v-if="item.options.length">选项：{{item.options.join(' / ')}}</p><p>答案：{{item.answer.values.join(' / ')}}</p><p v-if="item.points.length">知识点：{{item.points.join('、')}}</p></article><button v-if="importPreview" type="button" class="primary" :disabled="busy||!importPreview.can_import||!importKey" @click="commitImport">原子导入 {{importPreview.valid_count}} 道题</button></details><details :open="!!qid" class="bank-editor forum-card"><summary>{{qid?'编辑题目':'手动新增题目'}}</summary><form class="forum-form" @submit.prevent="saveQuestion"><h3>{{qid?'修订题目':'新增题目'}}</h3><label>所属题组（新增时设置）<select v-model="selectedGroup" :disabled="!!qid"><option :value="null">独立题</option><option v-for="g in groups" :key="g.id" :value="g.id">{{g.title}}</option></select></label><label>题型<select v-model="kind"><option v-for="(name,key) in kinds" :key="key" :value="key">{{name}}</option></select></label><label>题干<textarea v-model="body" required maxlength="20000" rows="4"></textarea></label><label v-if="['single','multiple'].includes(kind)">选项（每行一个）<textarea v-model="optionText" rows="4"></textarea></label><fieldset v-if="['single','multiple'].includes(kind)"><legend>点选正确答案（可暂空）</legend><label v-for="(o,i) in optionText.split('\n').filter(v=>v.trim())" :key="i"><input :type="kind==='single'?'radio':'checkbox'" name="bank-correct" :checked="answerText.split('\n').includes(String(i))" @change="answerText=kind==='single'?String(i):answerText.split('\n').includes(String(i))?answerText.split('\n').filter(v=>v!==String(i)).join('\n'):[...answerText.split('\n').filter(Boolean),String(i)].join('\n')">{{String.fromCharCode(65+i)}}. {{o}}</label><button type="button" class="secondary" @click="answerText=''">清空答案</button></fieldset><label v-else>答案 / 评分参考（选填；判断填 true/false，填空填等价答案）<textarea v-model="answerText" rows="3"></textarea></label><p>题库无需分值，组卷时逐题设置；无答案键的题目待教师人工批改。</p><label>题干配图<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy" @change="addPicture($event,'body')"></label><QuestionContent :text="body"/><label>解析<textarea v-model="explanation" rows="3"></textarea></label><fieldset><legend>知识点（可在论坛教师设置中新增）</legend><label v-for="p in points" :key="p.id"><input v-model="pointIds" type="checkbox" :value="p.id">{{p.name}}</label></fieldset><label><input v-model="active" type="checkbox">启用题目</label><button class="primary" :disabled="busy">保存题目</button><button type="button" class="secondary" @click="edit()">清空编辑</button></form></details><h3>题目列表</h3><form class="forum-actions" @submit.prevent="run(()=>loadBank())"><label>查找题目<input v-model="bankSearch" type="search" placeholder="输入题干关键词"></label><label>题型筛选<select v-model="bankKind" :disabled="busy"><option value="">全部题型</option><option v-for="(name,key) in kinds" :key="key" :value="key">{{name}}</option></select></label><label>知识点筛选<select v-model="bankPoint" :disabled="busy"><option value="">全部知识点</option><option v-for="p in points" :key="p.id" :value="String(p.id)">{{p.name}}</option></select></label><label>答案状态<select v-model="bankAnswer" :disabled="busy"><option value="">全部答案状态</option><option value="present">有参考答案</option><option value="missing">答案待补充</option></select></label><label>题目状态<select v-model="bankActive" :disabled="busy"><option value="">全部启用状态</option><option value="true">仅启用</option><option value="false">仅停用</option></select></label><button class="secondary" :disabled="busy">搜索题库</button><button type="button" class="secondary" :disabled="busy" @click="resetBankFilters">重置筛选</button></form><p>筛选只影响下方题目列表，不改变材料题组和已选题篮；有参考答案不代表已通过人工校对。</p><p v-if="!questions.length&&!busy">没有符合条件的题目，可重置筛选或新增题目。</p><article v-for="q in questions" :key="q.id" class="forum-card"><strong>{{kinds[q.kind]}} · {{q.answer?.values.length?'有参考答案':'答案待补充'}} · 版本 {{q.revision}} {{q.active===false?'已停用':''}}</strong><QuestionContent :text="q.body"/><p v-if="q.source_id">来源试卷 #{{q.source_id}} · 单元 {{q.source_units?.join('、')}}</p><button class="secondary" @click="edit(q)">编辑</button><button class="secondary" :disabled="busy" @click="toggleQuestion(q)">{{q.active===false?'恢复题目':'停用题目'}}</button><button v-if="!q.group" class="secondary" :disabled="q.active===false" @click="addCart('q'+q.id,q.body.slice(0,40),[q.id])">加入选题篮</button></article><button v-if="questionNext" class="secondary"  :disabled="busy" @click="run(()=>loadBank(questionNext!))">更多题目</button></template>
<form v-else-if="create&&isTeacher" class="forum-card forum-form" @submit.prevent="createQuiz"><h3>{{fixedIds.length?'创建固定试卷':'创建随机测验'}}</h3><section v-if="fixedIds.length"><p>按所选顺序组卷，共 {{fixedIds.length}} 小题，保留完整共享材料。</p><p role="status">全卷 {{assemblyTotal.toFixed(2)}} 分 · {{missingReferences}} 题缺少参考答案，需教师人工批改。</p><div class="forum-actions"><label>统一每题分值<input v-model="batchScore" type="number" min="0.01" max="99999.99" step="0.01"></label><button type="button" class="secondary" @click="applyBatchScore">应用到全卷</button><button type="button" class="secondary" @click="create=false;bank=true">返回选题</button></div><article v-for="(q,index) in assemblyQuestions" :key="q.id" class="forum-card"><section v-if="q.group&&(index===0||assemblyQuestions[index-1].group?.id!==q.group.id)"><h4>{{q.group.title}}</h4><QuestionContent :text="q.group.material"/></section><strong>{{index+1}}. {{kinds[q.kind]}} · 题 #{{q.id}}</strong><QuestionContent :text="q.body"/><div v-for="(option,i) in q.options" :key="i"><QuestionContent :text="String.fromCharCode(65+i)+'. '+option"/></div><p>{{q.answer?.values.length?'已有参考答案':'未设置答案键，将由教师人工批改'}}</p><label>题 #{{q.id}} 的分值<input v-model="fixedScores[q.id]" type="number" min="0.01" max="99999.99" step="0.01" required></label></article></section><label>测验标题<input v-model="quizTitle" required maxlength="200"></label><label>开放时间<input v-model="opens" type="datetime-local" required></label><label>关闭时间<input v-model="closes" type="datetime-local" required></label><label>答案解析统一公布时间（不得早于关闭）<input v-model="answersAt" type="datetime-local" required></label><label>限时（分钟）<input v-model.number="minutes" type="number" min="1" max="240" required></label><label>最大次数<input v-model.number="maxAttempts" type="number" min="1" max="10" required></label><label>取分策略：最高正式分，并列取较晚完成</label><template v-if="!fixedIds.length"><label>按知识点抽题<select v-model="rulePoint"><option value="">全部知识点</option><option v-for="p in points" :value="p.id">{{p.name}}</option></select></label><div v-for="(name,key) in kinds" :key="key" class="forum-actions">
  <label>{{name}}题数量<input v-model.number="counts[key]" type="number" min="0" max="50"></label>
  <label v-if="counts[key]>0">{{name}}每题分值<input v-model="randomScores[key]" type="number" min="0.01" max="99999.99" step="0.01" required></label>
</div></template><button class="primary" :disabled="busy">保存测验草稿</button></form>
<QuizAttemptPanel v-else-if="attempt" :attempt="attempt" :is-teacher="isTeacher" :answers="localAnswers" :scores="grade" :feedback="feedback" :reason="reason" :remaining="remaining" :save-state="saveState" :dirty="dirty" :saving="saving" :busy="busy" :ai-busy="aiBusy" :ai-status="aiStatus" :ai-elapsed="aiElapsed" :ai-items="aiItems" :ai-ready="aiReady" :error="error" :notice="notice" :suggestions="suggestions" @back="leaveAttempt" @changed="changed" @save="save" @submit="submit" @refresh="refreshAttempt" @review="review" @suggest="suggest" @adopt="adoptSuggestion" @reason="reason=$event" @upload="(q,event)=>upload(q,event)"/>
<template v-else-if="quiz"><button class="back" @click="quiz=null">← 返回测验列表</button><h3>{{quiz.title}}</h3><p>{{quiz.status==='draft'?'草稿':quiz.status==='closed'?'已关闭':'已发布'}} · 限时 {{quiz.time_limit_minutes}} 分钟 · 最多 {{quiz.max_attempts}} 次 · 取最高正式分</p><p>开放：{{new Date(quiz.opens_at).toLocaleString()}} 至 {{new Date(quiz.closes_at).toLocaleString()}}</p><p>答案公布：{{new Date(quiz.answers_at).toLocaleString()}}</p><div v-if="isTeacher" class="forum-actions"><button v-if="quiz.status==='draft'" class="primary" :disabled="busy" @click="action('publish')">校验题量并发布</button><button v-else class="secondary" :disabled="busy" @click="action('close')">关闭测验</button><button class="secondary" :disabled="busy" @click="action(quiz.grades_published?'grades_withdraw':'grades_publish')">{{quiz.grades_published?'撤回成绩公开':'发布完整成绩'}}</button><button class="secondary" @click="run(async()=>{stats=await api('quizzes/'+quiz!.id+'/statistics/')})">题目统计</button></div><button v-else class="primary" :disabled="busy" @click="start">开始 / 恢复作答</button><button class="secondary" :disabled="busy" @click="run(()=>loadAttempts())">刷新答卷</button><p v-if="!attempts.length">暂无答卷。</p><button v-for="a in attempts" :key="a.id" class="forum-card forum-post" @click="openAttempt(a.id)">{{a.student_name||'本人'}} · 第 {{a.number}} 次 · {{a.status==='submitted'?'已交卷':'作答中'}} · {{a.grading_status==='finalized'?'评分完成':'待评分'}} <span v-if="a.total!=null">{{a.total}} 分</span></button><button v-if="attemptNext" class="secondary" @click="run(()=>loadAttempts(attemptNext!))">更多答卷</button><section v-if="stats" class="forum-card"><h3>按试卷快照统计</h3><p>待复核 {{stats.pending_attempts}} 份；同快照、每人取最高正式分，并列取较晚完成；同分按学生 ID 稳定排序。</p><p v-if="!stats.groups.length">暂无完整正式评分样本。</p><div v-for="g in stats.groups" :key="g.snapshot_hash"><h4>快照 {{g.snapshot_hash.slice(0,8)}} · {{g.sample_size}} 人</h4><p v-for="q in g.questions" :key="q.question_id">题 #{{q.question_id}} · 全对率 {{(Number(q.full_correct_rate)*100).toFixed(1)}}% · 区分度 {{q.discrimination===null?'样本不足，不可计算':Number(q.discrimination).toFixed(3)}}</p></div></section></template>
<template v-else><p v-if="!loading&&!quizzes.length">暂无可见测验。</p><button v-for="q in quizzes" :key="q.id" class="forum-card forum-post" @click="select(q)"><strong>{{q.title}}</strong><small>{{q.status==='draft'?'草稿':q.status==='closed'?'已关闭':'已发布'}} · {{q.time_limit_minutes}} 分钟</small></button></template>
</section>
</template>
<style scoped>
.question-import{display:grid;gap:12px;min-width:0}.question-import .section-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap}.question-import input[type=file]{max-width:100%}.import-errors{color:#9d2f2f;padding-left:22px}.import-preview-row{border-top:1px solid #d9e3dd;padding:12px 0;min-width:0;overflow-wrap:anywhere}
</style>
